import { Comment, Role } from '@prisma/client';
import prisma from '../db';
import { BadRequestError, ForbiddenError, NotFoundError } from '../utils/AppError';

/**
 * 创建评论输入接口
 */
export interface CreateCommentInput {
  content: string;
  blogId: number;
  parentCommentId?: number | null;
  userId: number;
}

/**
 * 更新评论输入接口
 */
export interface UpdateCommentInput {
  content: string;
}

/**
 * 评论查询参数接口
 */
export interface GetCommentsParams {
  page?: number;
  limit?: number;
  sort?: 'createdAt' | 'updatedAt';
  order?: 'asc' | 'desc';
  parent?: boolean; // true: 仅顶级评论, false: 所有评论
}

/**
 * 分页评论列表返回接口
 */
export interface PaginatedComments {
  comments: any[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

/**
 * 嵌套评论结构接口
 */
export interface NestedComment {
  id: number;
  content: string;
  createdAt: Date;
  updatedAt: Date;
  blogId: number;
  userId: number;
  parentCommentId: number | null;
  user: {
    id: number;
    name: string;
    avatar: string | null;
  };
  blog?: {
    id: number;
    title: string;
  };
  parent?: {
    id: number;
    content: string;
    user: {
      id: number;
      name: string;
    };
  } | null;
  replies?: NestedComment[];
  replyCount: number;
  canEdit: boolean;
  canDelete: boolean;
}

/**
 * 创建评论
 */
export const createComment = async (input: CreateCommentInput) => {
  const { content, blogId, parentCommentId, userId } = input;

  // 验证博客是否存在
  const blog = await prisma.blog.findUnique({
    where: { id: blogId },
  });
  if (!blog) {
    throw new NotFoundError('博客不存在');
  }

  // 如果提供了父评论ID，验证父评论是否存在且属于同一博客
  if (parentCommentId) {
    const parentComment = await prisma.comment.findUnique({
      where: { id: parentCommentId },
      include: { blog: { select: { id: true } } },
    });
    if (!parentComment) {
      throw new NotFoundError('父评论不存在');
    }
    if (parentComment.blogId !== blogId) {
      throw new BadRequestError('父评论不属于该博客');
    }
  }

  // 创建评论
  const comment = await prisma.comment.create({
    data: {
      content,
      blogId,
      userId,
      parentCommentId: parentCommentId || null,
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  // 格式化返回数据
  return formatComment(comment, userId);
};

/**
 * 根据ID获取评论详情
 */
export const getCommentById = async (commentId: number, currentUserId?: number) => {
  const comment = await prisma.comment.findUnique({
    where: { id: commentId },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  if (!comment) {
    throw new NotFoundError('评论不存在');
  }

  return formatComment(comment, currentUserId);
};

/**
 * 检查用户是否有权操作评论（作者或管理员）
 */
const checkCommentPermission = async (commentId: number, userId: number, userRole: Role) => {
  if (userRole === Role.ADMIN) {
    return true;
  }

  const comment = await prisma.comment.findUnique({
    where: { id: commentId },
    select: { userId: true },
  });

  if (!comment) {
    throw new NotFoundError('评论不存在');
  }

  if (comment.userId !== userId) {
    throw new ForbiddenError('您没有权限操作此评论');
  }

  return true;
};

/**
 * 更新评论
 */
export const updateComment = async (
  commentId: number,
  input: UpdateCommentInput,
  userId: number,
  userRole: Role
) => {
  // 检查权限
  await checkCommentPermission(commentId, userId, userRole);

  const { content } = input;

  const updatedComment = await prisma.comment.update({
    where: { id: commentId },
    data: { content },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  return formatComment(updatedComment, userId);
};

/**
 * 删除评论（物理删除）
 */
export const deleteComment = async (
  commentId: number,
  userId: number,
  userRole: Role
) => {
  // 检查权限
  await checkCommentPermission(commentId, userId, userRole);

  // 删除评论（数据库已配置Cascade，会级联删除回复）
  const deletedComment = await prisma.comment.delete({
    where: { id: commentId },
    select: {
      id: true,
      content: true,
    },
  });

  return {
    message: '评论已成功删除',
    comment: deletedComment,
  };
};

/**
 * 获取博客的评论列表（支持嵌套结构）
 */
export const getBlogComments = async (
  blogId: number,
  params: GetCommentsParams,
  currentUserId?: number
) => {
  // 验证博客是否存在
  const blog = await prisma.blog.findUnique({
    where: { id: blogId },
  });
  if (!blog) {
    throw new NotFoundError('博客不存在');
  }

  const {
    page = 1,
    limit = 10,
    sort = 'createdAt',
    order = 'desc',
    parent = false, // 默认返回所有评论
  } = params;

  // 构建查询条件
  const where: any = { blogId };

  // 如果parent为true，只查询顶级评论（parentCommentId为null）
  if (parent === true) {
    where.parentCommentId = null;
  }

  // 计算总数
  const total = await prisma.comment.count({ where });

  // 计算总页数
  const totalPages = Math.ceil(total / limit);

  // 获取评论列表
  const comments = await prisma.comment.findMany({
    where,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: {
      [sort]: order,
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  // 格式化评论数据
  const formattedComments = comments.map(comment => 
    formatComment(comment, currentUserId)
  );

  // 如果parent为true，需要构建嵌套结构
  let nestedComments = formattedComments;
  if (parent === true) {
    nestedComments = buildNestedComments(formattedComments);
  }

  return {
    comments: nestedComments,
    pagination: {
      page,
      limit,
      total,
      totalPages,
    },
  };
};

/**
 * 获取用户的评论列表
 */
export const getUserComments = async (
  userId: number,
  params: GetCommentsParams,
  currentUserId?: number
) => {
  // 验证用户是否存在
  const user = await prisma.user.findUnique({
    where: { id: userId },
  });
  if (!user) {
    throw new NotFoundError('用户不存在');
  }

  const {
    page = 1,
    limit = 10,
    sort = 'createdAt',
    order = 'desc',
  } = params;

  // 构建查询条件
  const where = { userId };

  // 计算总数
  const total = await prisma.comment.count({ where });

  // 计算总页数
  const totalPages = Math.ceil(total / limit);

  // 获取评论列表
  const comments = await prisma.comment.findMany({
    where,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: {
      [sort]: order,
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  // 格式化评论数据
  const formattedComments = comments.map(comment => 
    formatComment(comment, currentUserId)
  );

  return {
    comments: formattedComments,
    pagination: {
      page,
      limit,
      total,
      totalPages,
    },
  };
};

/**
 * 获取评论的回复列表
 */
export const getCommentReplies = async (
  commentId: number,
  params: GetCommentsParams,
  currentUserId?: number
) => {
  // 验证评论是否存在
  const comment = await prisma.comment.findUnique({
    where: { id: commentId },
  });
  if (!comment) {
    throw new NotFoundError('评论不存在');
  }

  const {
    page = 1,
    limit = 10,
    sort = 'createdAt',
    order = 'asc', // 回复通常按时间升序排列
  } = params;

  // 构建查询条件：parentCommentId等于指定评论ID
  const where = { parentCommentId: commentId };

  // 计算总数
  const total = await prisma.comment.count({ where });

  // 计算总页数
  const totalPages = Math.ceil(total / limit);

  // 获取回复列表
  const replies = await prisma.comment.findMany({
    where,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: {
      [sort]: order,
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  // 格式化回复数据
  const formattedReplies = replies.map(reply => 
    formatComment(reply, currentUserId)
  );

  return {
    replies: formattedReplies,
    pagination: {
      page,
      limit,
      total,
      totalPages,
    },
  };
};

/**
 * 格式化评论数据
 */
const formatComment = (comment: any, currentUserId?: number): NestedComment => {
  const canEdit = currentUserId ? comment.userId === currentUserId : false;
  const canDelete = canEdit; // 目前只允许作者删除，管理员权限在控制器层处理

  return {
    id: comment.id,
    content: comment.content,
    createdAt: comment.createdAt,
    updatedAt: comment.updatedAt,
    blogId: comment.blogId,
    userId: comment.userId,
    parentCommentId: comment.parentCommentId,
    user: comment.user,
    blog: comment.blog,
    parent: comment.parent ? {
      id: comment.parent.id,
      content: comment.parent.content,
      user: comment.parent.user,
    } : null,
    replyCount: comment._count.replies,
    canEdit,
    canDelete,
  };
};

/**
 * 构建嵌套评论结构
 * 将平铺的评论列表转换为树形结构
 */
const buildNestedComments = (comments: NestedComment[]): NestedComment[] => {
  // 创建评论映射表
  const commentMap = new Map<number, NestedComment>();

  // 初始化所有评论，添加replies数组
  comments.forEach(comment => {
    commentMap.set(comment.id, { ...comment, replies: [] });
  });

  // 构建树形结构
  const rootComments: NestedComment[] = [];

  comments.forEach(comment => {
    const node = commentMap.get(comment.id)!;

    if (comment.parentCommentId) {
      // 如果有父评论，添加到父评论的replies中
      const parent = commentMap.get(comment.parentCommentId);
      if (parent) {
        parent.replies!.push(node);
      } else {
        // 父评论不在当前列表中，暂时作为根评论处理
        rootComments.push(node);
      }
    } else {
      // 顶级评论
      rootComments.push(node);
    }
  });

  return rootComments;
};

/**
 * 统计博客的评论数量
 */
export const countBlogComments = async (blogId: number) => {
  const totalComments = await prisma.comment.count({
    where: { blogId },
  });

  const topLevelComments = await prisma.comment.count({
    where: { 
      blogId,
      parentCommentId: null,
    },
  });

  return {
    total: totalComments,
    topLevel: topLevelComments,
  };
};

/**
 * 统计用户的评论数量
 */
export const countUserComments = async (userId: number) => {
  const total = await prisma.comment.count({
    where: { userId },
  });

  return { total };
};

