import { Request, Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import * as commentService from '../services/comment.service';
import { Role } from '@prisma/client';

/**
 * 扩展Express Request类型以包含user属性
 */
interface AuthenticatedRequest extends Request {
  user?: {
    userId: number;
    role: string;
  };
}

/**
 * 创建评论
 */
export const createComment = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 确保用户已认证
  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能发表评论',
    });
    return;
  }

  const {
    content,
    blogId,
    parentCommentId,
  } = req.body;

  const comment = await commentService.createComment({
    content,
    blogId: parseInt(blogId),
    parentCommentId: parentCommentId ? parseInt(parentCommentId) : null,
    userId: req.user.userId,
  });

  res.status(201).json({
    success: true,
    data: comment,
  });
});

/**
 * 获取单个评论详情
 */
export const getComment = asyncHandler(async (req: Request, res: Response) => {
  const commentId = parseInt(req.params.id);
  if (isNaN(commentId)) {
    res.status(400).json({
      success: false,
      error: '无效的评论ID',
    });
    return;
  }

  // 从请求中获取当前用户ID（如果已认证）
  const currentUserId = (req as AuthenticatedRequest).user?.userId;

  const comment = await commentService.getCommentById(commentId, currentUserId);

  res.status(200).json({
    success: true,
    data: comment,
  });
});

/**
 * 获取博客下的评论列表（支持嵌套结构）
 */
export const getCommentsByBlog = asyncHandler(async (req: Request, res: Response) => {
  const blogId = parseInt(req.params.blogId);
  if (isNaN(blogId)) {
    res.status(400).json({
      success: false,
      error: '无效的博客ID',
    });
    return;
  }

  const {
    page = '1',
    limit = '10',
    sort = 'createdAt',
    order = 'desc',
    parent,
  } = req.query;

  // 从请求中获取当前用户ID（如果已认证）
  const currentUserId = (req as AuthenticatedRequest).user?.userId;

  const params: commentService.GetCommentsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    sort: sort as 'createdAt' | 'updatedAt',
    order: order as 'asc' | 'desc',
    parent: parent === 'true' ? true : parent === 'false' ? false : undefined,
  };

  const result = await commentService.getBlogComments(blogId, params, currentUserId);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 更新评论
 */
export const updateComment = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const commentId = parseInt(req.params.id);
  if (isNaN(commentId)) {
    res.status(400).json({
      success: false,
      error: '无效的评论ID',
    });
    return;
  }

  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能更新评论',
    });
    return;
  }

  const { content } = req.body;

  const updatedComment = await commentService.updateComment(
    commentId,
    { content },
    req.user.userId,
    req.user.role as Role
  );

  res.status(200).json({
    success: true,
    data: updatedComment,
  });
});

/**
 * 删除评论
 */
export const deleteComment = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const commentId = parseInt(req.params.id);
  if (isNaN(commentId)) {
    res.status(400).json({
      success: false,
      error: '无效的评论ID',
    });
    return;
  }

  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能删除评论',
    });
    return;
  }

  const result = await commentService.deleteComment(
    commentId,
    req.user.userId,
    req.user.role as Role
  );

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 获取用户的评论列表
 */
export const getUserComments = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) {
    res.status(400).json({
      success: false,
      error: '无效的用户ID',
    });
    return;
  }

  // 检查权限：用户只能查看自己的评论，管理员可以查看任何用户的评论
  if (req.user?.role !== Role.ADMIN && req.user?.userId !== userId) {
    res.status(403).json({
      success: false,
      error: '您只能查看自己的评论',
    });
    return;
  }

  const {
    page = '1',
    limit = '10',
    sort = 'createdAt',
    order = 'desc',
  } = req.query;

  const currentUserId = req.user?.userId;

  const params: commentService.GetCommentsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    sort: sort as 'createdAt' | 'updatedAt',
    order: order as 'asc' | 'desc',
  };

  const result = await commentService.getUserComments(userId, params, currentUserId);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 获取评论的回复列表
 */
export const getReplies = asyncHandler(async (req: Request, res: Response) => {
  const commentId = parseInt(req.params.id);
  if (isNaN(commentId)) {
    res.status(400).json({
      success: false,
      error: '无效的评论ID',
    });
    return;
  }

  const {
    page = '1',
    limit = '10',
    sort = 'createdAt',
    order = 'asc',
  } = req.query;

  // 从请求中获取当前用户ID（如果已认证）
  const currentUserId = (req as AuthenticatedRequest).user?.userId;

  const params: commentService.GetCommentsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    sort: sort as 'createdAt' | 'updatedAt',
    order: order as 'asc' | 'desc',
  };

  const result = await commentService.getCommentReplies(commentId, params, currentUserId);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 统计博客评论数量
 */
export const countBlogComments = asyncHandler(async (req: Request, res: Response) => {
  const blogId = parseInt(req.params.blogId);
  if (isNaN(blogId)) {
    res.status(400).json({
      success: false,
      error: '无效的博客ID',
    });
    return;
  }

  const result = await commentService.countBlogComments(blogId);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 统计用户评论数量
 */
export const countUserComments = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) {
    res.status(400).json({
      success: false,
      error: '无效的用户ID',
    });
    return;
  }

  // 检查权限：用户只能查看自己的统计，管理员可以查看任何用户的统计
  if (req.user?.role !== Role.ADMIN && req.user?.userId !== userId) {
    res.status(403).json({
      success: false,
      error: '您只能查看自己的评论统计',
    });
    return;
  }

  const result = await commentService.countUserComments(userId);

  res.status(200).json({
    success: true,
    data: result,
  });
});

