import { Router } from 'express';
import * as commentController from '../controllers/comment.controller';
import * as commentValidation from '../validations/comment.validation';
import { requireAuth } from '../middleware/auth';
import { validate } from '../middleware/validate';

const router = Router();

/**
 * @route POST /api/comments
 * @desc 创建评论
 * @access Private
 */
router.post(
  '/',
  requireAuth,
  commentValidation.createCommentValidation,
  validate,
  commentController.createComment
);

/**
 * @route GET /api/comments/:id
 * @desc 获取单个评论详情
 * @access Public
 */
router.get(
  '/:id',
  commentValidation.commentIdValidation,
  validate,
  commentController.getComment
);

/**
 * @route PUT /api/comments/:id
 * @desc 更新评论
 * @access Private (作者或管理员)
 */
router.put(
  '/:id',
  requireAuth,
  commentValidation.updateCommentValidation,
  validate,
  commentController.updateComment
);

/**
 * @route DELETE /api/comments/:id
 * @desc 删除评论
 * @access Private (作者或管理员)
 */
router.delete(
  '/:id',
  requireAuth,
  commentValidation.commentIdValidation,
  validate,
  commentController.deleteComment
);

/**
 * @route GET /api/blogs/:blogId/comments
 * @desc 获取博客的评论列表（支持嵌套结构）
 * @access Public
 */
router.get(
  '/blogs/:blogId/comments',
  commentValidation.getBlogCommentsValidation,
  validate,
  commentController.getCommentsByBlog
);

/**
 * @route GET /api/users/:userId/comments
 * @desc 获取用户的评论列表
 * @access Private (用户只能查看自己的评论，管理员可以查看任何用户的评论)
 */
router.get(
  '/users/:userId/comments',
  requireAuth,
  commentValidation.getUserCommentsValidation,
  validate,
  commentController.getUserComments
);

/**
 * @route GET /api/comments/:id/replies
 * @desc 获取评论的回复列表
 * @access Public
 */
router.get(
  '/:id/replies',
  commentValidation.getCommentRepliesValidation,
  validate,
  commentController.getReplies
);

/**
 * @route GET /api/blogs/:blogId/comments/count
 * @desc 统计博客的评论数量
 * @access Public
 */
router.get(
  '/blogs/:blogId/comments/count',
  commentValidation.blogIdValidation,
  validate,
  commentController.countBlogComments
);

/**
 * @route GET /api/users/:userId/comments/count
 * @desc 统计用户的评论数量
 * @access Private (用户只能查看自己的统计，管理员可以查看任何用户的统计)
 */
router.get(
  '/users/:userId/comments/count',
  requireAuth,
  commentValidation.userIdValidation,
  validate,
  commentController.countUserComments
);

export default router;

