import { Request, Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import * as searchService from '../services/search.service';
import { BadRequestError } from '../utils/AppError';
import { BlogStatus } from '@prisma/client';
import { AuthenticatedRequest } from '../middleware/auth';

/**
 * 搜索博客文章
 */
export const searchBlogs = asyncHandler(async (req: Request, res: Response) => {
  const {
    q,                     // 搜索关键词
    category,              // 分类ID
    tag,                   // 标签ID（可多个，逗号分隔）
    author,                // 作者ID
    status = 'PUBLISHED',  // 博客状态（默认PUBLISHED）
    startDate,             // 开始日期（ISO格式）
    endDate,               // 结束日期（ISO格式）
    sort = 'relevance',    // 排序字段
    order = 'desc',        // 排序方向
    page = '1',            // 页码
    limit = '10',          // 每页数量
  } = req.query;

  // 必须提供搜索关键词
  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    throw new BadRequestError('搜索关键词是必需的');
  }

  // 解析标签ID数组
  let tagIds: number[] | undefined;
  if (tag) {
    if (typeof tag === 'string') {
      tagIds = tag.split(',').map(id => {
        const parsed = parseInt(id.trim(), 10);
        if (isNaN(parsed) || parsed <= 0) {
          throw new BadRequestError('标签ID必须是正整数');
        }
        return parsed;
      });
    } else {
      throw new BadRequestError('标签参数格式错误');
    }
  }

  // 解析其他ID参数
  const categoryId = category ? parseInt(category as string) : undefined;
  const authorId = author ? parseInt(author as string) : undefined;

  // 解析日期
  const startDateObj = startDate ? new Date(startDate as string) : undefined;
  const endDateObj = endDate ? new Date(endDate as string) : undefined;

  // 验证日期
  if (startDateObj && isNaN(startDateObj.getTime())) {
    throw new BadRequestError('开始日期格式无效');
  }
  if (endDateObj && isNaN(endDateObj.getTime())) {
    throw new BadRequestError('结束日期格式无效');
  }

  // 验证排序字段
  const validSortFields = ['relevance', 'createdAt', 'updatedAt', 'publishedAt', 'viewCount'];
  if (sort && !validSortFields.includes(sort as string)) {
    throw new BadRequestError(`排序字段必须是以下之一: ${validSortFields.join(', ')}`);
  }

  // 验证排序方向
  const validOrder = ['asc', 'desc'];
  if (order && !validOrder.includes(order as string)) {
    throw new BadRequestError('排序方向必须是 asc 或 desc');
  }

  // 验证状态
  const validStatus = Object.values(BlogStatus);
  if (status && !validStatus.includes(status as BlogStatus)) {
    throw new BadRequestError(`状态必须是以下之一: ${validStatus.join(', ')}`);
  }

  // 调用搜索服务
  const result = await searchService.searchBlogs({
    query: q.trim(),
    categoryId,
    tagIds,
    authorId,
    status: status as BlogStatus,
    startDate: startDateObj,
    endDate: endDateObj,
    sort: sort as 'relevance' | 'createdAt' | 'updatedAt' | 'publishedAt' | 'viewCount',
    order: order as 'asc' | 'desc',
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
  });

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 获取搜索建议（自动完成）
 */
export const searchSuggestions = asyncHandler(async (req: Request, res: Response) => {
  const { q } = req.query;

  // 如果未提供关键词，返回空数组
  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    res.status(200).json({
      success: true,
      data: [],
    });
    return;
  }

  const suggestions = await searchService.getSearchSuggestions(q.trim());

  res.status(200).json({
    success: true,
    data: suggestions,
  });
});

/**
 * 获取当前用户的搜索历史（需要认证）
 */
export const searchHistory = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 确保用户已认证
  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能查看搜索历史',
    });
    return;
  }

  const { page = '1', limit = '10' } = req.query;

  const history = await searchService.getUserSearchHistory(
    req.user.userId,
    parseInt(page as string) || 1,
    parseInt(limit as string) || 10
  );

  res.status(200).json({
    success: true,
    data: history,
  });
});

/**
 * 获取热门搜索关键词
 */
export const getPopularSearches = asyncHandler(async (req: Request, res: Response) => {
  const { period = 'today', limit = '10' } = req.query;

  const validPeriods = ['today', 'week', 'month', 'all'];
  if (!validPeriods.includes(period as string)) {
    throw new BadRequestError(`统计周期必须是以下之一: ${validPeriods.join(', ')}`);
  }

  const popularSearches = await searchService.getPopularSearches(
    period as 'today' | 'week' | 'month' | 'all',
    parseInt(limit as string) || 10
  );

  res.status(200).json({
    success: true,
    data: popularSearches,
  });
});

/**
 * 删除单条搜索历史记录（需要认证）
 */
export const deleteSearchHistory = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 确保用户已认证
  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能删除搜索历史',
    });
    return;
  }

  const historyId = parseInt(req.params.id as string);
  if (isNaN(historyId) || historyId <= 0) {
    throw new BadRequestError('无效的搜索历史ID');
  }

  await searchService.deleteSearchHistory(historyId, req.user.userId);

  res.status(200).json({
    success: true,
    data: { message: '搜索历史记录已删除' },
  });
});

/**
 * 清空当前用户的搜索历史（需要认证）
 */
export const clearSearchHistory = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 确保用户已认证
  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能清空搜索历史',
    });
    return;
  }

  await searchService.clearSearchHistory(req.user.userId);

  res.status(200).json({
    success: true,
    data: { message: '搜索历史已清空' },
  });
});

